import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken", "Oats", "Tofu", "Rice", "Beef", "Salmon"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Chicken": 6,
        "Oats": 2,
        "Tofu": 9,
        "Rice": 3,
        "Beef": 7,
        "Salmon": 9,
    },
    "content": {
        "Chicken": {"protein": 14, "carbs": 1, "calories": 164},
        "Oats": {"protein": 11, "carbs": 6, "calories": 210},
        "Tofu": {"protein": 8, "carbs": 12, "calories": 98},
        "Rice": {"protein": 1, "carbs": 17, "calories": 92},
        "Beef": {"protein": 16, "carbs": 11, "calories": 211},
        "Salmon": {"protein": 19, "carbs": 13, "calories": 211},
    },
    "requirement": {
        "protein": 70,
        "carbs": 117,
        "calories": 1837,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.servings = pyo.Var(model.F, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["cost"][f] * m.servings[f] for f in m.F)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][f][n] * m.servings[f] for f in m.F) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model


